// LAB: Separate calculation from presentation
// Extract a reusable sum operation and a formatter. Changing the label must not change the numeric result. Inputs are small integers whose sum fits in int.
// This starter verifies the original example. Extend it to satisfy the lab checks.
#include <cassert>
#include <iostream>
#include <sstream>

int main() {
    const int first = 7;
    const int second = 5;
    const int total = first + second;
    std::ostringstream message;
    message << "total=" << total;
    std::cout << message.str() << '\n';
    assert(total == 12);
}

#include <cassert>
#include <iostream>
#include <string>

int sum(int first, int second) { return first + second; }
std::string format(const std::string& label, int value) {
    return label + "=" + std::to_string(value);
}

int main() {
    assert(sum(7,5) == 12 && sum(-2,5) == 3);
    assert(format("sum",3) == "sum=3");
    std::cout << format("total",sum(7,5)) << '\n';
    std::cout << format("sum",sum(-2,5)) << '\n';
}

